function parseJson(value, fallback) {
  try {
    return value ? JSON.parse(value) : fallback;
  } catch (error) {
    return fallback;
  }
}

function coerceBool(value, fallback) {
  if (value === null || value === undefined) {
    return fallback;
  }

  const normalised = String(value).trim().toLowerCase();
  if (!normalised) {
    return fallback;
  }

  const truthy = new Set(['true', '1', 'yes', 'on']);
  const falsy = new Set(['false', '0', 'no', 'off']);
  if (truthy.has(normalised)) {
    return true;
  }
  if (falsy.has(normalised)) {
    return false;
  }
  return fallback;
}

function coerceNumber(value, fallback, { min } = { min: 0 }) {
  if (value === null || value === undefined) {
    return fallback;
  }
  const num = Number(value);
  if (!Number.isFinite(num) || num <= (min ?? 0)) {
    return fallback;
  }
  return num;
}

function normaliseValue(value) {
  return String(value ?? '').trim();
}

function dedupe(values) {
  const seen = new Set();
  const unique = [];
  for (const value of values) {
    if (!seen.has(value)) {
      seen.add(value);
      unique.push(value);
    }
  }
  return unique;
}

function normaliseLogin(login) {
  const base = String(login ?? '').trim().toLowerCase();
  if (!base) {
    return '';
  }
  return base.replace(/\[bot\]$/i, '');
}

function hasCliAgentLabel(labels) {
  if (!Array.isArray(labels)) {
    return false;
  }
  return labels.some((label) => label.startsWith('agent:'));
}

function countCheckboxes(markdown) {
  const result = { total: 0, checked: 0, unchecked: 0 };
  const regex = /(?:^|\n)\s*(?:[-*+]|\d+[.)])\s*\[( |x|X)\]/g;
  const content = String(markdown || '');
  let match;
  while ((match = regex.exec(content)) !== null) {
    result.total += 1;
    if ((match[1] || '').toLowerCase() === 'x') {
      result.checked += 1;
    } else {
      result.unchecked += 1;
    }
  }
  return result;
}

function resolveKeepalivePromptContext({ labels, checkboxCounts, options }) {
  const safeLabels = Array.isArray(labels) ? labels : [];
  const counts = checkboxCounts && typeof checkboxCounts === 'object' ? checkboxCounts : {};
  const total = Number.isFinite(counts.total) ? counts.total : 0;
  const unchecked = Number.isFinite(counts.unchecked) ? counts.unchecked : 0;
  const tasksComplete = total > 0 && unchecked === 0;
  const hasCiFailure = safeLabels.includes('ci-failure');

  const modeOverride = normaliseValue(options?.keepalive_prompt_mode ?? options?.prompt_mode);
  const scenarioOverride = normaliseValue(
    options?.keepalive_prompt_scenario ?? options?.prompt_scenario
  );

  let action = 'run';
  let reason = 'ready';
  let scenario = scenarioOverride;

  if (hasCiFailure) {
    action = 'fix';
    reason = 'ci-failure';
    if (!scenario) {
      scenario = 'ci-failure';
    }
  } else if (tasksComplete) {
    action = 'verify';
    reason = 'verify-acceptance';
    if (!scenario) {
      scenario = 'verification';
    }
  }

  return {
    mode: modeOverride,
    scenario,
    action,
    reason,
  };
}

